import{_ as e,a}from"./chunks/tokeness-models-dark-16x9.jOAvzOA9.js";import{_ as i,o as l,c as o,a2 as n}from"./chunks/framework.BZO4qERu.js";const b=JSON.parse('{"title":"Models and Billing","description":"Tokeness model pricing, billing basis, channel examples, usage logs, and cost control guidance.","frontmatter":{"title":"Models and Billing","description":"Tokeness model pricing, billing basis, channel examples, usage logs, and cost control guidance."},"headers":[],"relativePath":"billing/pricing.md","filePath":"billing/pricing.md","lastUpdated":1783700215000}'),s={name:"billing/pricing.md"};function d(r,t,c,h,p,m){return l(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="models-and-billing" tabindex="-1">Models and Billing <a class="header-anchor" href="#models-and-billing" aria-label="Permalink to &quot;Models and Billing&quot;">​</a></h1><p>Tokeness uses a prepaid billing model. Each API call is deducted based on actual consumption. Model prices are authoritative in the console, the model marketplace, or a formal quotation.</p><figure class="tokeness-shot"><div class="tokeness-shot-frame"><img class="tokeness-shot-light" src="'+e+'" alt="Tokeness model marketplace"><img class="tokeness-shot-dark" src="'+a+'" alt="Tokeness model marketplace"></div><figcaption>Model marketplace</figcaption></figure><h2 id="billing-basis" tabindex="-1">Billing Basis <a class="header-anchor" href="#billing-basis" aria-label="Permalink to &quot;Billing Basis&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Description</th></tr></thead><tbody><tr><td>Payment method</td><td>Prepaid — top up before calling</td></tr><tr><td>Deduction method</td><td>API call consumption is deducted from the account balance in real time</td></tr><tr><td>Balance validity</td><td>Balance remains valid long-term; specifics are subject to platform policy</td></tr><tr><td>Price unit</td><td>Input and output prices are shown per 1M tokens</td></tr><tr><td>Exchange rate assumption</td><td>Current channel price tables are converted at <code>1 USD = 7 CNY</code></td></tr></tbody></table><h2 id="channel-examples" tabindex="-1">Channel Examples <a class="header-anchor" href="#channel-examples" aria-label="Permalink to &quot;Channel Examples&quot;">​</a></h2><p>The channel price table includes the following common categories:</p><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Official-relay channel</td><td>Shown at official API list price or with zero markup</td></tr><tr><td>Discount channel</td><td>Some models such as Claude and GPT have different discount channels</td></tr><tr><td>Domestic models</td><td>Domestic models are shown at the Tokeness channel price based on the official list price</td></tr><tr><td>Partner</td><td>After reaching a monthly volume threshold, discounts can be stacked on top of non-official-relay prices</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Price changes</p><p>Model supplier prices, exchange rates, and channel policies may all change. Public documentation only describes the billing method and does not commit to fixed prices.</p></div><h2 id="viewing-consumption" tabindex="-1">Viewing Consumption <a class="header-anchor" href="#viewing-consumption" aria-label="Permalink to &quot;Viewing Consumption&quot;">​</a></h2><p>After making calls, you can view the following in the console:</p><table tabindex="0"><thead><tr><th>Page</th><th>Purpose</th></tr></thead><tbody><tr><td>Overview</td><td>View account and call summary</td></tr><tr><td>Data dashboard</td><td>Analyze model call and consumption trends</td></tr><tr><td>Usage logs</td><td>Inspect individual request status, model, and cost</td></tr><tr><td>Wallet</td><td>View balance and top up</td></tr></tbody></table><h2 id="cost-control" tabindex="-1">Cost Control <a class="header-anchor" href="#cost-control" aria-label="Permalink to &quot;Cost Control&quot;">​</a></h2><ol><li>Use a separate API key for each project.</li><li>Set a smaller quota for development and test environments.</li><li>Run high-consumption workflows with a small sample first.</li><li>Review usage logs and the data dashboard regularly.</li><li>Split keys by client for channel or client projects.</li></ol>',14)])])}const f=i(s,[["render",d]]);export{b as __pageData,f as default};
